<h2>1. Linked Lists — Self-Referential Structures</h2>
<div class="theory-box">
<strong>Core Concept:</strong> A linked list is a dynamic sequence of <strong>nodes</strong> — each node is a heap-allocated struct containing a data payload and a pointer to the next node. Unlike arrays, nodes are <em>not contiguous in memory</em>; the list's structure exists entirely through pointer links. This enables O(1) insertion/deletion at known positions but sacrifices O(1) random access.
</div>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct Node {
    int data;
    struct Node *next;   // Self-referential: pointer to same struct type
} Node;

Node* createNode(int val) {
    Node *n = (Node*)malloc(sizeof(Node));
    if (!n) { perror("malloc"); exit(1); }
    n->data = val;
    n->next = NULL;
    return n;
}

Node* insertFront(Node *head, int val) {  // O(1)
    Node *n = createNode(val);
    n->next = head;
    return n;
}

Node* insertEnd(Node *head, int val) {    // O(n)
    Node *n = createNode(val);
    if (!head) return n;
    Node *curr = head;
    while (curr->next) curr = curr->next;
    curr->next = n;
    return head;
}

Node* deleteByValue(Node *head, int target) {
    if (!head) return NULL;
    if (head->data == target) {
        Node *tmp = head->next;
        free(head);
        return tmp;
    }
    Node *curr = head;
    while (curr->next && curr->next->data != target)
        curr = curr->next;
    if (curr->next) {
        Node *tmp = curr->next->next;
        free(curr->next);
        curr->next = tmp;
    }
    return head;
}

void freeList(Node *head) {    // ALWAYS free all nodes when done!
    while (head) { Node *tmp = head; head = head->next; free(tmp); }
}</code></pre>

<h2>2. Stacks (LIFO) and Queues (FIFO)</h2>
<pre><code>#define MAX 100
// ── STACK ── (Last In, First Out)
typedef struct { int data[MAX]; int top; } Stack;
void  stackInit(Stack *s)       { s->top = -1; }
int   stackEmpty(Stack *s)      { return s->top == -1; }
int   stackFull(Stack *s)       { return s->top == MAX-1; }
void  push(Stack *s, int v)     { if (!stackFull(s))  s->data[++s->top] = v; }
int   pop(Stack *s)             { if (!stackEmpty(s)) return s->data[s->top--]; return -1; }
int   peek(Stack *s)            { if (!stackEmpty(s)) return s->data[s->top];   return -1; }

// ── QUEUE ── (First In, First Out) — Circular Array
typedef struct { int data[MAX]; int front, rear, size; } Queue;
void  queueInit(Queue *q)       { q->front=0; q->rear=-1; q->size=0; }
int   queueEmpty(Queue *q)      { return q->size==0; }
void  enqueue(Queue *q, int v)  {
    if (q->size==MAX) return;
    q->rear = (q->rear+1) % MAX;   // Circular wrap-around
    q->data[q->rear] = v;
    q->size++;
}
int   dequeue(Queue *q) {
    if (queueEmpty(q)) return -1;
    int v = q->data[q->front];
    q->front = (q->front+1) % MAX; // Circular wrap-around
    q->size--;
    return v;
}</code></pre>

<h2>3. Binary Search Tree (BST)</h2>
<div class="theory-box">
<strong>Core Concept:</strong> A BST enforces the <strong>ordering property</strong>: every node's left subtree contains only keys <em>less than</em> the node's key; every right subtree contains only keys <em>greater than</em> the node's key. This property enables O(log n) average search, insert, and delete. In-order traversal produces keys in <em>sorted ascending order</em>.
</div>
<pre><code>typedef struct BSTNode { int key; struct BSTNode *left, *right; } BSTNode;

BSTNode* bstInsert(BSTNode *root, int key) {
    if (!root) {
        BSTNode *n = malloc(sizeof(BSTNode));
        n->key=key; n->left=n->right=NULL; return n;
    }
    if (key < root->key)      root->left  = bstInsert(root->left,  key);
    else if (key > root->key) root->right = bstInsert(root->right, key);
    return root;   // Equal key: ignore duplicate
}

void inOrder(BSTNode *root) {   // Produces SORTED output!
    if (!root) return;
    inOrder(root->left);
    printf("%d ", root->key);
    inOrder(root->right);
}

BSTNode* bstSearch(BSTNode *root, int key) {
    if (!root || root->key == key) return root;
    if (key < root->key) return bstSearch(root->left,  key);
    else                 return bstSearch(root->right, key);
}</code></pre>

<h2>4. Hash Tables with Separate Chaining</h2>
<pre><code>#define TABLE_SIZE 17   // Prime number: reduces clustering in modulo hashing
typedef struct HNode { int key; int value; struct HNode *next; } HNode;
typedef struct { HNode *buckets[TABLE_SIZE]; } HashTable;

int hashFunc(int key) { return abs(key) % TABLE_SIZE; }

void htInsert(HashTable *ht, int key, int val) {
    int idx = hashFunc(key);
    HNode *n = malloc(sizeof(HNode));
    n->key=key; n->value=val;
    n->next = ht->buckets[idx];   // Insert at HEAD of chain (O(1))
    ht->buckets[idx] = n;
}

int htGet(HashTable *ht, int key) {
    for (HNode *n = ht->buckets[hashFunc(key)]; n; n = n->next)
        if (n->key == key) return n->value;
    return -1;   // Not found
}
// Average O(1) operations when load factor (n/TABLE_SIZE) is low (~0.7)</code></pre>

<h2>5. Big O Complexity Reference Matrix</h2>
<table class="comparison-table">
<tr><th>Operation</th><th>Array</th><th>Singly LL</th><th>BST (avg)</th><th>Hash Table</th></tr>
<tr><td>Access by index</td><td>O(1)</td><td>O(n)</td><td>—</td><td>—</td></tr>
<tr><td>Search</td><td>O(n)</td><td>O(n)</td><td>O(log n)</td><td>O(1)</td></tr>
<tr><td>Insert (front)</td><td>O(n)</td><td>O(1)</td><td>O(log n)</td><td>O(1)</td></tr>
<tr><td>Insert (end)</td><td>O(1)*</td><td>O(n)</td><td>O(log n)</td><td>O(1)</td></tr>
<tr><td>Delete</td><td>O(n)</td><td>O(n)</td><td>O(log n)</td><td>O(1)</td></tr>
<tr><td>Memory</td><td>Static, compact</td><td>Dynamic, fragmented</td><td>Dynamic</td><td>Dynamic + overhead</td></tr>
</table>
<div class="info-box"><strong>Key Principle:</strong> No single data structure is best for all operations. Choose based on your dominant access pattern: frequent indexed access → array; frequent front insertions → linked list; sorted data + range queries → BST; fast key-value lookup → hash table.</div>
"}

