<h2>1. File Handling Internals & Binary Streams</h2>
<div class="theory-box">
<strong>Core Concept:</strong> C provides two abstraction layers for file access. The high-level <strong>FILE* stream</strong> (from <code>&lt;stdio.h&gt;</code>) wraps a raw OS handle with user-space buffering, error flags, and a position counter. The low-level <strong>POSIX file descriptor</strong> (an integer) is the raw kernel handle used directly by system calls. For binary data, use <code>"rb"/"wb"</code> modes with <code>fread()/fwrite()</code> to avoid text-translation overhead.
</div>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

typedef struct { int id; double freq; char label[32]; } TelemetryRecord;

int main(void) {
    // Binary WRITE: struct directly to disk
    FILE *fp = fopen("data.bin", "wb");
    if (!fp) { perror("fopen"); return 1; }

    TelemetryRecord rec = {42, 9.8, "Sensor-Alpha"};
    size_t written = fwrite(&rec, sizeof(TelemetryRecord), 1, fp);
    printf("Wrote %zu record(s)\n", written);
    fclose(fp);

    // Binary READ with random access
    fp = fopen("data.bin", "rb");
    if (!fp) { perror("fopen"); return 1; }

    TelemetryRecord readBack;
    fseek(fp, 0, SEEK_SET);   // Jump to beginning
    fread(&readBack, sizeof(TelemetryRecord), 1, fp);
    printf("ID=%d Freq=%.1f Label=%s\n",
           readBack.id, readBack.freq, readBack.label);

    long pos = ftell(fp);     // Current file position in bytes
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);    // File size
    printf("Read at byte %ld of %ld\n", pos, size);
    fclose(fp);
    return 0;
}</code></pre>

<h2>2. I/O Buffering Systems</h2>
<div class="theory-box">
<strong>Core Concept:</strong> By default, C streams are <strong>fully buffered</strong> for files (flush when buffer fills) and <strong>line buffered</strong> for terminals (flush on newline). Buffering dramatically reduces the number of expensive system calls. <code>setvbuf()</code> lets you override this for precise control — essential for real-time logging and high-throughput I/O.
</div>
<pre><code>#include &lt;stdio.h&gt;

// Three buffering modes:
// _IOFBF: Fully Buffered  — flush when buffer fills (default for files)
// _IOLBF: Line Buffered   — flush on '\n' (default for terminals)
// _IONBF: Unbuffered      — immediate I/O (used for stderr)

char mybuf[8192];
setvbuf(stdout, mybuf, _IOFBF, sizeof(mybuf));  // Custom 8KB stdout buffer
// printf() won't output until buffer fills OR fflush() is called

fflush(stdout);   // Force flush to OS immediately

// Unbuffered stderr: critical errors appear immediately even if stdout buffers
setvbuf(stderr, NULL, _IONBF, 0);
fprintf(stderr, "Critical error: immediate output!\n");</code></pre>

<h2>3. Command-Line Arguments & Environment Variables</h2>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main(int argc, char *argv[]) {
    // argc: total argument count including program name
    // argv[0]: program name, argv[1..argc-1]: actual arguments

    printf("Program: %s\n", argv[0]);
    printf("Arguments (%d):\n", argc - 1);
    for (int i = 1; i < argc; i++)
        printf("  argv[%d] = \"%s\"\n", i, argv[i]);

    // Run as: ./program hello world 42
    // → argv[1]="hello", argv[2]="world", argv[3]="42"

    // Environment variables
    const char *path = getenv("PATH");
    const char *home = getenv("HOME");
    if (path) printf("PATH (first 60): %.60s...\n", path);
    if (home) printf("HOME: %s\n", home);

    // setenv: set or override environment variable
    setenv("MY_APP_MODE", "production", 1);   // 1 = overwrite if exists
    printf("Mode: %s\n", getenv("MY_APP_MODE"));

    return 0;
}</code></pre>

<h2>4. Process Architecture — fork/exec/wait</h2>
<div class="theory-box">
<strong>Core Concept:</strong> On Unix/Linux, new processes are created with <strong>fork()</strong> — which creates an exact copy of the current process. The copy (child) gets return value 0; the original (parent) gets the child's PID. <strong>exec()</strong> replaces the child's entire program image with a new executable. <strong>wait()/waitpid()</strong> makes the parent block until the child finishes, preventing zombie processes.
</div>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/wait.h&gt;
#include &lt;stdlib.h&gt;

int main(void) {
    pid_t pid = fork();   // Create child process

    if (pid < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) {
        // ── CHILD PROCESS (fork returns 0 to child) ──
        printf("Child PID: %d | Parent PID: %d\n", getpid(), getppid());

        // exec: REPLACE this process image with ls -la
        execlp("ls", "ls", "-la", NULL);  // Never returns on success!
        perror("exec failed");            // Only reached if exec fails
        exit(1);
    } else {
        // ── PARENT PROCESS (fork returns child's PID to parent) ──
        printf("Parent PID: %d | Created child: %d\n", getpid(), pid);

        int status;
        waitpid(pid, &status, 0);   // Block until child finishes

        if (WIFEXITED(status))
            printf("Child exited with code: %d\n", WEXITSTATUS(status));
    }
    return 0;
}</code></pre>

<h2>5. Signal Handling with sigaction</h2>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;signal.h&gt;
#include &lt;unistd.h&gt;

volatile sig_atomic_t running = 1;  // sig_atomic_t: safe to set from signal handler

void sigintHandler(int signum) {
    // Keep this function SHORT and async-signal-safe
    // DO NOT call printf, malloc, or other non-reentrant functions here!
    running = 0;   // Signal the main loop to exit cleanly
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);          // Don't block other signals during handler
    sa.sa_flags = SA_RESTART;         // Auto-restart interrupted system calls

    sigaction(SIGINT, &sa, NULL);     // Register handler for Ctrl+C

    printf("Running. Press Ctrl+C to stop.\n");
    while (running) {
        sleep(1);
        printf("tick...\n");
    }
    printf("\nClean shutdown complete.\n");
    return 0;
}</code></pre>

<h2>6. Anonymous Pipes — Inter-Process Communication</h2>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;unistd.h&gt;
#include &lt;string.h&gt;
#include &lt;sys/wait.h&gt;

int main(void) {
    int pipefd[2];    // pipefd[0] = READ end, pipefd[1] = WRITE end
    if (pipe(pipefd) == -1) { perror("pipe"); return 1; }

    pid_t pid = fork();
    if (pid == 0) {
        // ── CHILD: reads from pipe ──
        close(pipefd[1]);          // Child doesn't need write end
        char buf[128] = {0};
        ssize_t n = read(pipefd[0], buf, sizeof(buf)-1);
        buf[n] = '\0';
        printf("Child received: \"%s\"\n", buf);
        close(pipefd[0]);
    } else {
        // ── PARENT: writes to pipe ──
        close(pipefd[0]);          // Parent doesn't need read end
        const char *msg = "Hello from parent process!";
        write(pipefd[1], msg, strlen(msg));
        close(pipefd[1]);          // Closing write end sends EOF to child
        wait(NULL);
    }
    return 0;
}</code></pre>
