    def __init__(self):
        self.entries:
        list[str] = []
    def record(self, statement: str) -&gt; None:
        self.entries.append(statement)
class CommercialAccount:
    &quot;&quot;&quot;Master account class leveraging composition rather than multiple inheritance.&quot;&quot;&quot;
    def __init__(self, owner: str, initial_balance: float):
        self.owner = owner
        # Composed Object Entities
        self.balance = MonetaryAmount(initial_balance)
